BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷100·高祖本纪·天福十二年八月李肃致仕", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/jiuwudaishi-100-li-su-retirement/source.txt", "note": "《旧五代史》卷100·高祖本纪·天福十二年八月李肃致仕，段落 jiu-wudaishi-205deb4a7860-p002438；已核上下文及传主，纸本及异文待核。", "id": "09d6b615-0654-5ce1-bb6d-2dd967dc81e3"}, {"title": "旧五代史·卷109·李守贞传·河中陷落", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/jiuwudaishi-109-li-shouzhen-death/source.txt", "note": "《旧五代史》卷109·李守贞传·河中陷落，段落 jiu-wudaishi-205deb4a7860-p002625；已核上下文及传主，纸本及异文待核。", "id": "4e5f0ea3-2d7f-52f6-aa38-3d9f7f89943c"}, {"title": "旧五代史·卷109·赵思绾传·请降与被杀", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/jiuwudaishi-109-zhao-surrender-949/source.txt", "note": "《旧五代史》卷109·赵思绾传·请降与被杀，段落 jiu-wudaishi-205deb4a7860-p002628；已核上下文及传主，纸本及异文待核。", "id": "41ad5092-8b8e-50fa-abb3-da7f5c709922"}, {"title": "宋史·卷249·王溥传·河中焚书", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/songshi-249-wang-pu-hezhong/source.txt", "note": "《宋史》卷249·王溥传·河中焚书，段落 songshi-9c6e46fee832-p057123；已核上下文及传主，纸本及异文待核。", "id": "92264b88-a82c-582e-b83d-c85639a3c4c3"}, {"title": "资治通鉴·卷288·乾祐二年·六月至八月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/tongjian-288-949-june-july/source.txt", "note": "《资治通鉴》卷288·乾祐二年·六月至八月，段落 zizhi-tongjian-a63549944a71-p003424；已核上下文及传主，纸本及异文待核。", "id": "a9b57512-1ba4-5b10-b3c3-6a8f96e53250"}, {"title": "资治通鉴·卷288·乾祐二年·赵思绾请降及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/tongjian-288-949-zhao-surrender/source.txt", "note": "《资治通鉴》卷288·乾祐二年·赵思绾请降及追述，段落 zizhi-tongjian-a63549944a71-p003423；已核上下文及传主，纸本及异文待核。", "id": "333e0689-657e-5298-88c7-3ed7fa4e3a39"}, {"title": "新五代史·卷53·赵思绾传·请降与被杀", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/xinwudaishi-053-zhao-surrender/source.txt", "note": "《新五代史》卷53·赵思绾传·请降与被杀，段落 xin-wudaishi-b08f244b9241-p002074；已核上下文及传主，纸本及异文待核。", "id": "fd81d60b-87fe-5a26-a8ae-4fae59deab2c"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-102-may-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年五月，段落 jiu-wudaishi-205deb4a7860-p002474；已核上下文及传主，纸本及异文待核。", "id": "5f60206d-10da-54a0-9b9b-aed2fca2bf32"}, {"title": "旧五代史·卷110·周太祖纪·河中之役", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-110-guo-hezhong-949/source.txt", "note": "《旧五代史》卷110·周太祖纪·河中之役，段落 jiu-wudaishi-205deb4a7860-p002635；已核上下文及传主，纸本及异文待核。", "id": "3215db1b-e4b9-597e-b981-6b30a3a4ae28"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "李肃（晋昌节度副使）", "aliases": ["李肅（晉昌節度副使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年赵在礼入朝后，留在长安的部将作乱，他以晋昌节度副使身份平定叛乱。原文籍贯写建人，疑有缺字，未补成具体地名；暂未与936年单州刺史同名人合并，生卒年未载。", "biography": null, "status": "draft", "id": "b968dc74-a8d5-5cf5-b7a9-67006da04ac9"}, {"name": "张氏（李肃妻）", "aliases": ["张夫人", "張氏（李肅妻）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张全义的女儿、李肃的妻子，个人名字与生卒年未载。《通鉴》记她劝李肃厚赠赵思绾，后来又劝丈夫让赵思绾归顺后汉。早期赠物的经过与《旧五代史》附注有所不同，分别保留。", "biography": null, "status": "draft", "id": "ec6719ed-2922-57ca-9596-264396ef3f76"}, {"name": "张全义", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受封者。", "biography": null, "status": "draft", "id": "3d89e670-5812-57eb-a061-8aaea77bd5e8"}, {"name": "程让能", "aliases": ["程讓能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思绾的判官。949年与李肃劝赵思绾归顺后汉，《旧五代史》还记他起草章表。《新五代史》写陈让能，保留姓氏异说，未凭字形另建第二个人。生卒年未载。", "biography": null, "status": "draft", "id": "babdd821-2695-5cb9-ba93-877b6f4d78df"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "常彦卿", "aliases": ["常彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思绾党羽。948年部队被召赴京时，赵思绾向其表达忧惧，常彦卿建议临机应变，不要再说。生卒年未载。", "biography": null, "status": "draft", "id": "aae86d4a-7087-5ec9-95db-380c022a92b1"}, {"name": "钭滔", "aliases": ["鈄滔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内牙都指挥使，史书记为胡进思的党羽。949年有人告发他谋叛，钱弘俶不愿深入追究，将他贬到处州。告发涉及钱弘亿，未据此认定两人确已谋反。生卒年未载。", "biography": null, "status": "draft", "id": "5ceb033c-3de5-5abf-a509-c7e7685e392d"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "钱弘亿", "aliases": ["錢弘億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "11129a7d-ca77-5d63-b3fd-b341fb184b7e"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "李崇勋", "aliases": ["李崇勳"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞的儿子。《通鉴》记949年七月壬戌与父母等自焚。旧史附注另有李崇训的名字，尚待校核，不在本批直接合并。生年未载。", "biography": null, "status": "draft", "id": "e3152438-b798-5300-9139-766489e283eb"}, {"name": "李崇玉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞的儿子。949年七月河中城陷时被郭威俘获，送到大梁处死。生年未载。", "biography": null, "status": "draft", "id": "0821ef7d-4321-5dab-860d-88a29f91f57d"}, {"name": "靖余", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞任命的宰相。949年河中城陷时被俘，送到大梁处死。《通鉴》姓名中带有无法正常显示的字形，本批据《旧五代史》同一被俘、处死名单写作靖余，原文保留，纸本姓名待核。", "biography": null, "status": "draft", "id": "906ccba9-4d00-587d-a76f-fbceed90871f"}, {"name": "孙愿", "aliases": ["孫願"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞任命的宰相。949年七月河中城陷时被俘，送到大梁处死。生年及此前经历未载。", "biography": null, "status": "draft", "id": "f82a2168-5895-5b07-b77d-a572a90e3b35"}, {"name": "刘芮", "aliases": ["劉芮"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞任命的枢密使。949年七月河中城陷时被俘，送到大梁处死。生年及此前经历未载。", "biography": null, "status": "draft", "id": "4dc3d030-554d-5fa6-9bb6-9453c3419902"}, {"name": "总伦", "aliases": ["總倫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞门下僧人，以方术预言李守贞将成为皇帝，受到其相信。《新五代史》也记总伦以方术影响李守贞，预言均按说话者的主张记录。生卒年未载。", "biography": null, "status": "draft", "id": "079788d1-e6b4-52de-b2df-58b27472ca5f"}, {"name": "赵修己", "aliases": ["趙修己"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "浚仪人，擅长术数。李守贞镇滑州时任司户参军，随后随李守贞移镇。948年叛乱前多次劝其不要轻动，未获采纳，称病回乡。生卒年未载，未将后周同名司天官的经历无证并入。", "biography": null, "status": "draft", "id": "466921a0-4aca-54da-a351-22bfaf8a12b0"}, {"name": "王溥（后周宋初）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "949年为秘书郎，在河中平定后劝郭威焚毁涉及朝臣、藩镇的往来书信，《宋史》王溥传也记此事。与901年条所载同名王溥分开建档。生卒年留待具体原文补录。", "biography": null, "status": "draft", "id": "13d3b7ec-869a-5019-ac41-39e5abcd2df3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

